import type { RecipeSeed } from './recipes'

export const recipeAdditionSeeds: RecipeSeed[] = [
  { id:'thai-chicken-cashew-stir-fry', sourceId:'slice3-01', name:'ผัดไก่เม็ดมะม่วงแบบไทย', englishName:'Thai Chicken Cashew Stir-fry', category:'Quick meals', cuisine:'Thai', servings:2, prepMinutes:15, cookMinutes:16, ingredients:[{item:'Skinless chicken breast, sliced',amount:'280 g'},{item:'Unsalted cashews',amount:'30 g'},{item:'Bell pepper, sliced',amount:'1 medium'},{item:'Onion, sliced',amount:'1 medium'},{item:'Mushrooms, sliced',amount:'150 g'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Neutral oil',amount:'1 tsp'},{item:'Jasmine rice, cooked',amount:'1 cup'}], instructions:['Toast the cashews in a dry pan and set them aside.','Heat half the oil and sear the chicken until lightly browned and almost cooked.','Add the remaining oil, onion, bell pepper and mushrooms; stir-fry until tender, then add garlic for the final 30 seconds.','Add soy sauce and 2 tablespoons of water, return the chicken and cashews, toss until glossy and serve with rice.'], nutrition:{kcal:440,protein:35,carbs:45,fat:14,fiber:6,sodium:560}, tags:['High protein','Quick','Balanced'], accent:'gold' },
  { id:'thai-red-curry-chicken-green-beans', sourceId:'slice3-02', name:'แกงเผ็ดไก่ถั่วแขก', englishName:'Thai Red Curry Chicken with Green Beans', category:'Thai favorites', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:20, ingredients:[{item:'Skinless chicken thighs, sliced',amount:'280 g'},{item:'Light coconut milk',amount:'200 ml'},{item:'Red curry paste',amount:'1 tbsp'},{item:'Green beans, cut',amount:'160 g'},{item:'Bell pepper, sliced',amount:'1 medium'},{item:'Thai basil leaves',amount:'½ cup'},{item:'Fish sauce',amount:'1 tsp'},{item:'Jasmine rice, cooked',amount:'1 cup'}], instructions:['Stir the curry paste in a warm pan until fragrant.','Add coconut milk and green beans and simmer until the beans are nearly tender.','Add chicken and bell pepper and simmer until the chicken is cooked through.','Season with fish sauce, fold in Thai basil off the heat and serve with rice.'], nutrition:{kcal:490,protein:33,carbs:48,fat:18,fiber:7,sodium:650}, tags:['High protein','Balanced','Gluten-free'], accent:'red' },
  { id:'thai-garlic-prawns-brown-rice', sourceId:'slice3-03', name:'กุ้งผัดกระเทียมพริกมะนาว', englishName:'Thai Garlic Prawns with Lime', category:'Quick meals', cuisine:'Thai', servings:2, prepMinutes:10, cookMinutes:10, ingredients:[{item:'Prawns, peeled',amount:'260 g'},{item:'Garlic, minced',amount:'4 cloves'},{item:'Bird’s eye chilli, sliced',amount:'1'},{item:'Green beans, cut',amount:'180 g'},{item:'Oyster sauce',amount:'1 tbsp'},{item:'Lime juice',amount:'1 tbsp'},{item:'Neutral oil',amount:'1 tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Heat the oil and cook garlic and chilli until fragrant without browning the garlic.','Add prawns and stir-fry until almost opaque.','Add green beans and 3 tablespoons of water, cover for 2 minutes, then uncover and add oyster sauce.','Cook until the prawns are fully opaque, turn off the heat, add lime juice and serve with rice.'], nutrition:{kcal:390,protein:30,carbs:40,fat:10,fiber:6,sodium:640}, tags:['High protein','Quick','Dairy-free'], accent:'lime' },
  { id:'thai-pork-ginger-stirfry', sourceId:'slice3-04', name:'ผัดหมูขิงเห็ด', englishName:'Thai Pork and Ginger Stir-fry', category:'High protein', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:12, ingredients:[{item:'Lean pork loin, thinly sliced',amount:'280 g'},{item:'Ginger, julienned',amount:'2 tbsp'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Onion, sliced',amount:'1 medium'},{item:'Mushrooms, sliced',amount:'180 g'},{item:'Oyster sauce',amount:'1 tbsp'},{item:'Reduced-sodium soy sauce',amount:'1 tsp'},{item:'Neutral oil',amount:'1 tsp'},{item:'Jasmine rice, cooked',amount:'1 cup'}], instructions:['Heat oil and stir-fry ginger and garlic for 30 seconds.','Add pork and cook until the edges brown.','Add onion and mushrooms with 2 tablespoons of water and cook until tender.','Add oyster sauce and soy sauce, toss until the pork is cooked through and serve with rice.'], nutrition:{kcal:450,protein:36,carbs:44,fat:14,fiber:5,sodium:720}, tags:['High protein','Quick','Balanced'], accent:'aqua' },
  { id:'thai-glass-noodle-chicken-stirfry', sourceId:'slice3-05', name:'ผัดวุ้นเส้นไก่แบบไทย', englishName:'Thai Chicken Glass Noodle Stir-fry', category:'Quick meals', cuisine:'Thai', servings:2, prepMinutes:15, cookMinutes:14, ingredients:[{item:'Skinless chicken breast, sliced',amount:'240 g'},{item:'Glass noodles, dry',amount:'80 g'},{item:'Cabbage, shredded',amount:'200 g'},{item:'Carrot, julienned',amount:'1 medium'},{item:'Mushrooms, sliced',amount:'120 g'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Oyster sauce',amount:'1 tbsp'},{item:'Reduced-sodium soy sauce',amount:'1 tsp'},{item:'Sesame oil',amount:'1 tsp'}], instructions:['Soak or cook the glass noodles according to the packet, then drain well.','Warm sesame oil, stir-fry garlic and chicken until the chicken is nearly cooked.','Add cabbage, carrot and mushrooms with 3 tablespoons of water; cook until tender-crisp.','Add noodles, oyster sauce and soy sauce, toss until hot and serve.'], nutrition:{kcal:420,protein:28,carbs:52,fat:11,fiber:6,sodium:690}, tags:['High protein','Quick','Dairy-free'], accent:'violet' },
  { id:'thai-tofu-peanut-lime-noodles', sourceId:'slice3-06', name:'เส้นโฮลวีตเต้าหู้ซอสถั่วมะนาว', englishName:'Thai Tofu Peanut-Lime Noodles', category:'Plant-forward', cuisine:'Thai', servings:2, prepMinutes:15, cookMinutes:12, ingredients:[{item:'Whole-wheat noodles, cooked',amount:'280 g'},{item:'Firm tofu, sliced',amount:'240 g'},{item:'Natural peanut butter',amount:'1½ tbsp'},{item:'Lime juice',amount:'2 tbsp'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Bean sprouts',amount:'1 cup'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Neutral oil',amount:'1 tsp'}], instructions:['Heat the oil and sear tofu until golden on both sides, then set it aside.','Whisk peanut butter, lime juice, soy sauce, garlic and 3 tablespoons of warm water into a pourable sauce.','Toss the noodles and bean sprouts with the sauce until coated and warmed through.','Top with cucumber and tofu and serve immediately.'], nutrition:{kcal:500,protein:23,carbs:64,fat:16,fiber:8,sodium:620}, tags:['Vegetarian','Plant protein','Quick'], accent:'gold' },
  {"id":"thai-massaman-chicken-sweet-potato","sourceId":"slice3-07","name":"แกงมัสมั่นไก่มันหวาน","englishName":"Thai Massaman Chicken with Sweet Potato","category":"Thai favorites","cuisine":"Thai","servings":2,"prepMinutes":15,"cookMinutes":26,"ingredients":[{"item":"Skinless chicken thighs, sliced","amount":"280 g"},{"item":"Light coconut milk","amount":"200 ml"},{"item":"Red curry paste","amount":"1½ tbsp"},{"item":"Curry powder","amount":"1 tsp"},{"item":"Cinnamon","amount":"¼ tsp"},{"item":"Ground cardamom","amount":"¼ tsp"},{"item":"Sweet potato, cubed","amount":"280 g"},{"item":"Onion, sliced","amount":"1 small"},{"item":"Fish sauce","amount":"1 tsp"},{"item":"Brown sugar","amount":"1 tsp"},{"item":"Lime juice","amount":"1 tbsp"},{"item":"Roasted peanuts, chopped","amount":"1 tbsp"},{"item":"Jasmine rice, cooked","amount":"1 cup"}],"instructions":["Warm 3 tablespoons of the coconut milk with red curry paste, curry powder, cinnamon and cardamom for 1 minute. This warm-spice mixture is a practical Massaman-style paste substitute.","Add the remaining coconut milk, 100 ml water, 1.5 cm sweet-potato cubes and onion; simmer covered for 10–12 minutes until nearly tender.","Add chicken, fish sauce, sugar and half the peanuts. Simmer gently for 6–8 minutes until chicken is fully cooked and sweet potato is tender; reduce uncovered to a coating curry.","Turn off the heat and add lime juice for a mild sour finish. Taste for a balanced sweet, salty and sour flavor; loosen with water if too concentrated. Top with remaining peanuts and serve with rice."],"nutrition":{"kcal":567,"protein":33,"carbs":62,"fat":22,"fiber":7,"sodium":825},"tags":["High protein","Comforting","Balanced"],"accent":"coral"},
  { id:'thai-steamed-salmon-chilli-lime', sourceId:'slice3-08', name:'ปลาแซลมอนนึ่งมะนาวพริก', englishName:'Thai Steamed Salmon with Chilli-Lime Sauce', category:'High protein', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:15, ingredients:[{item:'Salmon fillets',amount:'280 g'},{item:'Garlic, minced',amount:'3 cloves'},{item:'Lime juice',amount:'2 tbsp'},{item:'Fish sauce',amount:'1 tbsp'},{item:'Bird’s eye chilli, sliced',amount:'1'},{item:'Chinese celery, sliced',amount:'½ cup'},{item:'Jasmine rice, cooked',amount:'1 cup'}], instructions:['Place salmon on a heatproof plate and steam until it flakes easily, about 12–15 minutes.','Mix garlic, lime juice, fish sauce and chilli with 2 tablespoons of warm water.','Rest the salmon for 2 minutes, spoon over the sauce and top with Chinese celery.','Serve with jasmine rice.'], nutrition:{kcal:430,protein:31,carbs:35,fat:18,fiber:2,sodium:760}, tags:['High protein','Omega-rich','Gluten-free'], accent:'aqua' },
  { id:'thai-pumpkin-chickpea-salad', sourceId:'slice3-09', name:'สลัดฟักทองย่างถั่วชิกพี', englishName:'Thai Roasted Pumpkin Chickpea Salad', category:'Plant-forward', cuisine:'Thai', servings:2, prepMinutes:15, cookMinutes:22, ingredients:[{item:'Chickpeas, rinsed',amount:'1½ cups'},{item:'Pumpkin, cubed',amount:'300 g'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Shallot, sliced',amount:'¼ cup'},{item:'Mint leaves',amount:'½ cup'},{item:'Lime juice',amount:'2 tbsp'},{item:'Reduced-sodium soy sauce',amount:'1 tsp'},{item:'Toasted rice powder',amount:'1 tbsp'},{item:'Olive oil',amount:'1 tsp'},{item:'Dried chilli flakes',amount:'½ tsp'}], instructions:['Toss pumpkin with olive oil and roast at 200°C until tender and lightly browned, about 20 minutes.','Whisk lime juice, soy sauce, toasted rice powder and chilli into a dressing.','Combine warm pumpkin with chickpeas, cucumber, shallot and mint.','Toss with the dressing and serve while the pumpkin is warm.'], nutrition:{kcal:360,protein:13,carbs:52,fat:10,fiber:14,sodium:470}, tags:['Vegan','Fiber-rich','Light'], accent:'lime' },
  { id:'thai-egg-fried-rice-prawns', sourceId:'slice3-10', name:'ข้าวผัดข้าวกล้องกุ้งแบบไทย', englishName:'Thai Prawn Brown Rice Fried Rice', category:'Quick meals', cuisine:'Thai', servings:2, prepMinutes:10, cookMinutes:12, ingredients:[{item:'Prawns, peeled',amount:'200 g'},{item:'Brown rice, cooked',amount:'1½ cups'},{item:'Eggs',amount:'2'},{item:'Green peas',amount:'½ cup'},{item:'Carrot, diced',amount:'1 medium'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Neutral oil',amount:'1 tsp'},{item:'Spring onion, sliced',amount:'2 stalks'}], instructions:['Heat oil and stir-fry garlic and carrot until fragrant and slightly tender.','Push the vegetables aside, scramble the eggs, then add prawns and cook until nearly opaque.','Add rice and peas, toss over high heat, then season with soy sauce.','Fold in spring onion and cook until the prawns are fully opaque.'], nutrition:{kcal:470,protein:27,carbs:62,fat:12,fiber:7,sodium:650}, tags:['High protein','Quick','Balanced'], accent:'coral' },
  {"id":"thai-tom-yum-tofu-noodles","sourceId":"slice3-11","name":"ก๋วยเตี๋ยวต้มยำเต้าหู้","englishName":"Thai Tom Yum Tofu Noodles","category":"Quick meals","cuisine":"Thai","servings":2,"prepMinutes":12,"cookMinutes":16,"ingredients":[{"item":"Whole-wheat noodles, cooked","amount":"200 g"},{"item":"Firm tofu, cubed","amount":"200 g"},{"item":"Tom yum herbs","amount":"1 small bundle"},{"item":"Mushrooms, sliced","amount":"200 g"},{"item":"Low-sodium vegetable stock","amount":"600 ml"},{"item":"Lime juice","amount":"2 tbsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Bird’s eye chilli, sliced","amount":"1"}],"instructions":["Simmer stock with tom yum herbs for 5 minutes to infuse the broth.","Add mushrooms and tofu and simmer until the mushrooms are tender and the tofu is hot.","Divide cooked noodles between bowls and ladle over the broth.","Season with soy sauce, lime juice and chilli just before serving."],"nutrition":{"kcal":370,"protein":20,"carbs":45,"fat":11,"fiber":7,"sodium":620},"tags":["Vegetarian","Quick","Light"],"accent":"violet"},
  { id:'thai-green-curry-white-fish', sourceId:'slice3-12', name:'แกงเขียวหวานปลากับถั่วแขก', englishName:'Thai Green Curry White Fish', category:'Thai favorites', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:18, ingredients:[{item:'White fish fillets, cubed',amount:'280 g'},{item:'Green curry paste',amount:'1 tbsp'},{item:'Light coconut milk',amount:'200 ml'},{item:'Green beans, cut',amount:'150 g'},{item:'Bell pepper, sliced',amount:'1 medium'},{item:'Lime juice',amount:'1 tbsp'},{item:'Fish sauce',amount:'1 tsp'},{item:'Jasmine rice, cooked',amount:'1 cup'}], instructions:['Stir green curry paste in a warm pan until fragrant.','Add coconut milk and green beans and simmer until the beans are nearly tender.','Add fish and bell pepper and poach gently until the fish is opaque and flakes.','Season with fish sauce and lime juice and serve over jasmine rice.'], nutrition:{kcal:440,protein:31,carbs:48,fat:14,fiber:6,sodium:610}, tags:['High protein','Gluten-free','Balanced'], accent:'green' },
  {"id":"japanese-beef-tofu-sukiyaki","sourceId":"slice3-13","name":"สุกี้ยากี้เนื้อเต้าหู้","englishName":"Japanese Beef and Tofu Sukiyaki","category":"High protein","cuisine":"Japanese","servings":2,"prepMinutes":15,"cookMinutes":20,"ingredients":[{"item":"Lean beef strips","amount":"260 g"},{"item":"Firm tofu, cubed","amount":"200 g"},{"item":"Napa cabbage, chopped","amount":"250 g"},{"item":"Mushrooms, sliced","amount":"150 g"},{"item":"Glass noodles, dry","amount":"60 g"},{"item":"Reduced-sodium soy sauce","amount":"3 tbsp"},{"item":"Brown sugar","amount":"2 tsp"},{"item":"Rice vinegar","amount":"1 tsp"},{"item":"Neutral oil","amount":"1 tsp"},{"item":"Spring onion, sliced","amount":"2 stalks"},{"item":"Brown rice, cooked","amount":"1 cup"}],"instructions":["Cook glass noodles according to the packet and drain. Mix soy sauce, sugar, rice vinegar and 120 ml water as a sweet Japanese-style cooking liquid, a home substitute for mirin-based warishita, not Thai suki dipping sauce.","Heat oil in a wide pan, briefly brown the thin beef strips, and transfer to a clean plate. Add cabbage, mushrooms and the cooking liquid; simmer covered for 5 minutes.","Add tofu and noodles. Simmer uncovered for 3–4 minutes, turning gently until flavored and the liquid is slightly reduced; add a splash of water only if the pan dries.","Return beef and its juices; simmer until cooked through, about 1–2 minutes. Finish with spring onion and serve with brown rice."],"nutrition":{"kcal":656,"protein":55,"carbs":67,"fat":21,"fiber":7,"sodium":996},"tags":["High protein","Comforting","Meal prep"],"accent":"red"},
  {"id":"japanese-chicken-miso-ginger-bowl","sourceId":"slice3-14","name":"ข้าวหน้าไก่มิโสะขิง","englishName":"Japanese Miso Ginger Chicken Bowl","category":"High protein","cuisine":"Japanese","servings":2,"prepMinutes":12,"cookMinutes":16,"ingredients":[{"item":"Skinless chicken thighs, sliced","amount":"280 g"},{"item":"White miso","amount":"1 tbsp"},{"item":"Ginger, grated","amount":"1 tbsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tsp"},{"item":"Cabbage, shredded","amount":"250 g"},{"item":"Carrot, julienned","amount":"1 medium"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Sesame seeds","amount":"1 tsp"},{"item":"Neutral oil","amount":"1 tsp"}],"instructions":["Pat chicken dry. Mix miso, ginger and soy sauce with 2 tablespoons of water in a separate bowl.","Heat oil in a non-stick pan and brown the chicken for 4–5 minutes, turning once; transfer to a clean plate.","Add cabbage, carrot and 3 tablespoons of water; cover for 3 minutes until crisp-tender. Return chicken and its juices, add the miso mixture and simmer uncovered until chicken is fully cooked and the glaze coats everything.","Serve over brown rice and finish with sesame."],"nutrition":{"kcal":415,"protein":32,"carbs":38,"fat":16,"fiber":6,"sodium":584},"tags":["High protein","Balanced","Meal prep"],"accent":"gold"},
  {"id":"japanese-tofu-teriyaki-vegetables","sourceId":"slice3-15","name":"เต้าหู้เทอริยากิกับผัก","englishName":"Japanese Teriyaki Tofu with Vegetables","category":"Plant-forward","cuisine":"Japanese","servings":2,"prepMinutes":12,"cookMinutes":15,"ingredients":[{"item":"Firm tofu, cubed","amount":"300 g"},{"item":"Reduced-sodium teriyaki sauce","amount":"3 tbsp"},{"item":"Broccoli florets","amount":"220 g"},{"item":"Mushrooms, sliced","amount":"150 g"},{"item":"Ginger, grated","amount":"1 tsp"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Sesame seeds","amount":"1 tsp"}],"instructions":["Pat tofu dry and pan-sear in a non-stick pan until golden on two sides; set aside.","Cook broccoli, mushrooms and ginger with 3 tablespoons of water, covered for 3 minutes until crisp-tender. Uncover and evaporate excess water.","Return tofu, add teriyaki sauce and toss over medium heat for 1–2 minutes until a thin glossy glaze coats the tofu and vegetables. Add a tablespoon of water only if too thick.","Serve over brown rice and finish with sesame."],"nutrition":{"kcal":422,"protein":36,"carbs":44,"fat":15,"fiber":9,"sodium":530},"tags":["Vegetarian","Plant protein","Balanced"],"accent":"lime"},
  {"id":"japanese-soba-mushroom-soup","sourceId":"slice3-16","name":"โซบะเห็ดในน้ำซุปผักญี่ปุ่น","englishName":"Japanese Soba Mushroom Soup","category":"Light bowls","cuisine":"Japanese","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"item":"Buckwheat soba","amount":"150 g"},{"item":"Mushrooms, sliced","amount":"200 g"},{"item":"Low-sodium vegetable stock","amount":"500 ml"},{"item":"Firm tofu, cubed","amount":"200 g"},{"item":"Spinach","amount":"100 g"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Rice vinegar","amount":"1 tbsp"},{"item":"Ginger, julienned","amount":"1 tbsp"},{"item":"Spring onion, sliced","amount":"2 stalks"}],"instructions":["Cook soba according to the packet, rinse briefly and drain.","Simmer stock with ginger and mushrooms until the mushrooms are tender.","Add tofu and spinach and heat until the tofu is hot and the spinach wilts; season with soy sauce and rice vinegar.","Divide soba into bowls, ladle over the soup and finish with spring onion."],"nutrition":{"kcal":370,"protein":22,"carbs":52,"fat":8,"fiber":7,"sodium":690},"tags":["Vegetarian","Light","Quick"],"accent":"blue"},
  {"id":"japanese-eggplant-miso-donburi","sourceId":"slice3-17","name":"ข้าวหน้ามิโสะมะเขือยาว","englishName":"Japanese Miso Eggplant Donburi","category":"Plant-forward","cuisine":"Japanese","servings":2,"prepMinutes":12,"cookMinutes":20,"ingredients":[{"item":"Eggplant, sliced","amount":"280 g"},{"item":"Firm tofu, cubed","amount":"220 g"},{"item":"White miso","amount":"2 tbsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tsp"},{"item":"Ginger, grated","amount":"1 tsp"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Spring onion, sliced","amount":"2 stalks"},{"item":"Sesame seeds","amount":"1 tsp"},{"item":"Neutral oil","amount":"2 tsp"},{"item":"Brown sugar","amount":"1 tsp"},{"item":"Rice vinegar","amount":"1 tsp"}],"instructions":["Pat tofu dry. Heat half the oil in a non-stick pan and sear tofu until golden; set aside.","Heat the remaining oil and brown eggplant slices for 3–4 minutes per side. Add ginger and 3 tablespoons of water, cover for 3 minutes until tender, then uncover to evaporate excess water.","Mix miso, soy sauce, sugar and rice vinegar with 2 tablespoons of water. Add tofu and this glaze; toss gently over low heat until coated, without scorching the miso.","Spoon over brown rice and finish with spring onion and sesame."],"nutrition":{"kcal":411,"protein":26,"carbs":44,"fat":17,"fiber":10,"sodium":757},"tags":["Vegetarian","Plant protein","Fiber-rich"],"accent":"violet"},
  {"id":"japanese-tamago-edamame-rice","sourceId":"slice3-18","name":"ข้าวญี่ปุ่นไข่และถั่วแระ","englishName":"Japanese Tamago Edamame Rice","category":"Quick meals","cuisine":"Japanese","servings":2,"prepMinutes":10,"cookMinutes":12,"ingredients":[{"item":"Cooked sushi rice","amount":"1½ cups"},{"item":"Eggs","amount":"3"},{"item":"Shelled edamame","amount":"120 g"},{"item":"Spinach","amount":"100 g"},{"item":"Low-sodium vegetable stock","amount":"60 ml"},{"item":"Reduced-sodium soy sauce","amount":"1 tsp"},{"item":"Sesame seeds","amount":"1 tsp"},{"item":"Nori sheets","amount":"2 sheets"}],"instructions":["Use a 24 cm non-stick pan. Simmer vegetable stock and soy sauce with edamame for 3 minutes, add spinach and cook until wilted; reduce uncovered until only a thin layer of liquid remains.","Pour in beaten eggs, cover over low heat for 2–3 minutes until softly set with no liquid white remaining.","Gently fold the soft egg and vegetable mixture through warm sushi rice; the rice should be moist, not surrounded by broth.","Top with sesame and torn nori before serving."],"nutrition":{"kcal":392,"protein":23,"carbs":50,"fat":12,"fiber":6,"sodium":278},"tags":["Vegetarian","Quick","Balanced"],"accent":"aqua"},
  {"id":"japanese-tuna-miso-lettuce-bowl","sourceId":"slice3-19","name":"ข้าวหน้าทูน่ามิโสะและผักกาดหอม","englishName":"Japanese Tuna Miso Lettuce Bowl","category":"Light bowls","cuisine":"Japanese","servings":2,"prepMinutes":12,"cookMinutes":0,"ingredients":[{"item":"Tuna in spring water, drained","amount":"200 g"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Lettuce, shredded","amount":"100 g"},{"item":"Cucumber, sliced","amount":"1 small"},{"item":"Avocado, sliced","amount":"½"},{"item":"White miso","amount":"1 tbsp"},{"item":"Rice vinegar","amount":"1 tbsp"},{"item":"Sesame seeds","amount":"1 tsp"},{"item":"Nori sheets","amount":"2 sheets"}],"instructions":["Mix miso and rice vinegar with 1 tablespoon of water, then fold through the tuna.","Divide cooled brown rice and shredded lettuce between bowls; arrange cucumber and avocado alongside.","Spoon the tuna mixture over the rice and lettuce.","Finish with sesame and torn nori and serve chilled."],"nutrition":{"kcal":350,"protein":33,"carbs":36,"fat":9,"fiber":7,"sodium":600},"tags":["High protein","No-cook","Dairy-free"],"accent":"aqua"},
  {"id":"korean-chicken-dakgalbi","sourceId":"slice3-20","name":"ทัคคัลบีไก่ผัก","englishName":"Korean Chicken Dakgalbi","category":"High protein","cuisine":"Korean","servings":2,"prepMinutes":15,"cookMinutes":20,"ingredients":[{"item":"Skinless chicken thighs, sliced","amount":"300 g"},{"item":"Cabbage, chopped","amount":"250 g"},{"item":"Sweet potato, cut into 1 cm cubes","amount":"250 g"},{"item":"Gochujang","amount":"1½ tbsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Ginger, grated","amount":"1 tsp"},{"item":"Sesame seeds","amount":"1 tsp"},{"item":"Brown rice, cooked","amount":"1 cup"}],"instructions":["Mix gochujang, soy sauce, garlic and ginger with 2 tablespoons of water and coat the chicken.","Place 1 cm sweet-potato cubes and 80 ml water in a wide non-stick pan. Cover and simmer for 7–9 minutes until a knife almost slides through; add a splash of water if the pan dries.","Add chicken with its sauce and cabbage. Cook for 7–9 minutes, turning frequently, until chicken is fully cooked and sweet potato tender. Uncover for the final 2 minutes to reduce the sauce to a coating.","Serve with brown rice and sesame."],"nutrition":{"kcal":520,"protein":32,"carbs":56,"fat":18,"fiber":8,"sodium":780},"tags":["High protein","Balanced","Comforting"],"accent":"red"},
  { id:'korean-pork-gochujang-stirfry', sourceId:'slice3-21', name:'หมูผัดซอสโคชูจัง', englishName:'Korean Gochujang Pork Stir-fry', category:'Quick meals', cuisine:'Korean', servings:2, prepMinutes:12, cookMinutes:14, ingredients:[{item:'Lean pork loin, thinly sliced',amount:'280 g'},{item:'Gochujang',amount:'1 tbsp'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Ginger, grated',amount:'1 tsp'},{item:'Onion, sliced',amount:'1 medium'},{item:'Cabbage, shredded',amount:'180 g'},{item:'Sesame seeds',amount:'1 tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Whisk gochujang, soy sauce, garlic and ginger with 2 tablespoons of water.','Sear the pork in a hot non-stick pan until the edges brown.','Add onion and cabbage and stir-fry until tender, then pour in the sauce and reduce until it coats the pork.','Serve with brown rice and sesame.'], nutrition:{kcal:480,protein:35,carbs:47,fat:16,fiber:6,sodium:790}, tags:['High protein','Quick','Balanced'], accent:'coral' },
  {"id":"korean-beef-glass-noodles","sourceId":"slice3-22","name":"วุ้นเส้นเกาหลีเนื้อและผัก","englishName":"Korean Beef Glass Noodles","category":"Quick meals","cuisine":"Korean","servings":2,"prepMinutes":15,"cookMinutes":15,"ingredients":[{"item":"Lean beef strips","amount":"240 g"},{"item":"Glass noodles, Korean sweet-potato, dry","amount":"90 g"},{"item":"Spinach","amount":"120 g"},{"item":"Carrot, julienned","amount":"1 medium"},{"item":"Mushrooms, sliced","amount":"120 g"},{"item":"Reduced-sodium soy sauce","amount":"2 tbsp"},{"item":"Sesame oil","amount":"2 tsp"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Sesame seeds","amount":"1 tsp"},{"item":"Brown sugar","amount":"2 tsp"},{"item":"Onion, thinly sliced","amount":"1 small"}],"instructions":["Marinate beef for 10 minutes with half the soy sauce, half the sugar, garlic and half the sesame oil. Cook Korean sweet-potato glass noodles according to the packet, drain and cut once or twice with scissors.","Sear beef in a hot non-stick pan in one layer for 2–3 minutes until browned and cooked; transfer to a clean plate.","Use the remaining sesame oil to brown onion and mushrooms for 4–5 minutes. Add carrot with 2 tablespoons of water and cook until crisp-tender, then wilt the spinach.","Add noodles, remaining soy sauce and sugar, and 2 tablespoons of water. Toss until the sweet-savory glaze is absorbed, return beef and its juices to heat through, and finish with sesame."],"nutrition":{"kcal":470,"protein":32,"carbs":55,"fat":14,"fiber":4,"sodium":735},"tags":["High protein","Quick","Meal prep"],"accent":"red"},
  { id:'korean-tuna-kimchi-rice', sourceId:'slice3-23', name:'ข้าวผัดกิมจิทูน่าใส่ไข่', englishName:'Korean Tuna Kimchi Rice with Egg', category:'Quick meals', cuisine:'Korean', servings:2, prepMinutes:10, cookMinutes:14, ingredients:[{item:'Tuna in spring water, drained',amount:'200 g'},{item:'Kimchi, chopped',amount:'150 g'},{item:'Brown rice, cooked',amount:'1½ cups'},{item:'Eggs',amount:'2'},{item:'Gochujang',amount:'1 tsp'},{item:'Sesame oil',amount:'1 tsp'},{item:'Spring onion, sliced',amount:'2 stalks'}], instructions:['Heat sesame oil and cook kimchi until softened and fragrant.','Add brown rice, tuna and gochujang and toss until hot and well coated.','Push the rice aside, scramble the eggs, then fold them through the rice.','Finish with spring onion and serve immediately.'], nutrition:{kcal:480,protein:28,carbs:60,fat:14,fiber:5,sodium:940}, tags:['High protein','Quick','Balanced'], accent:'red' },
  { id:'korean-tofu-kimchi-lettuce-wraps', sourceId:'slice3-24', name:'ห่อผักกาดเต้าหู้กิมจิ', englishName:'Korean Tofu Kimchi Lettuce Wraps', category:'Plant-forward', cuisine:'Korean', servings:2, prepMinutes:12, cookMinutes:12, ingredients:[{item:'Firm tofu, sliced',amount:'280 g'},{item:'Kimchi, vegan, chopped',amount:'150 g'},{item:'Butter lettuce leaves',amount:'12 leaves'},{item:'Brown rice, cooked',amount:'1 cup'},{item:'Gochujang',amount:'1 tsp'},{item:'Cucumber, matchsticks',amount:'1 small'},{item:'Garlic, minced',amount:'1 clove'},{item:'Sesame seeds',amount:'1 tsp'}], instructions:['Pan-sear tofu until golden on both sides and set it aside.','Cook vegan kimchi with garlic and gochujang for 3 minutes until softened.','Arrange lettuce leaves with brown rice, cucumber, tofu and warm kimchi.','Finish with sesame and fold the leaves around the filling.'], nutrition:{kcal:420,protein:23,carbs:44,fat:16,fiber:8,sodium:870}, tags:['Vegetarian','Plant protein','Light'], accent:'lime' },
  { id:'korean-beef-spinach-soup', sourceId:'slice3-25', name:'ซุปเนื้อผักโขมเกาหลี', englishName:'Korean Beef and Spinach Soup', category:'Light bowls', cuisine:'Korean', servings:2, prepMinutes:10, cookMinutes:18, ingredients:[{item:'Lean beef strips',amount:'240 g'},{item:'Low-sodium stock',amount:'650 ml'},{item:'Spinach',amount:'150 g'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Sesame oil',amount:'1 tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Bring stock to a simmer and add garlic.','Add beef and cook until just tender, then add spinach and simmer until wilted.','Season with soy sauce and sesame oil.','Serve the soup with brown rice.'], nutrition:{kcal:380,protein:29,carbs:38,fat:12,fiber:5,sodium:680}, tags:['High protein','Light','Gluten-free'], accent:'violet' },
  {"id":"korean-egg-tofu-stew","sourceId":"slice3-26","name":"สตูว์เต้าหู้ไข่เกาหลี","englishName":"Korean Egg and Tofu Stew","category":"Plant-forward","cuisine":"Korean","servings":2,"prepMinutes":10,"cookMinutes":18,"ingredients":[{"item":"Firm tofu, cubed","amount":"300 g"},{"item":"Eggs","amount":"2"},{"item":"Zucchini, sliced","amount":"1 medium"},{"item":"Mushrooms, sliced","amount":"150 g"},{"item":"Low-sodium vegetable stock","amount":"500 ml"},{"item":"Gochujang","amount":"1 tsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Spring onion, sliced","amount":"2 stalks"},{"item":"Brown rice, cooked","amount":"1 cup"}],"instructions":["Simmer stock with garlic and gochujang for 5 minutes.","Add zucchini, mushrooms and tofu and cook until the vegetables are tender.","Season with soy sauce, crack in the eggs, cover and cook until the whites set.","Finish with spring onion and serve with brown rice."],"nutrition":{"kcal":430,"protein":24,"carbs":50,"fat":15,"fiber":7,"sodium":720},"tags":["Vegetarian","Plant protein","Comforting"],"accent":"aqua"},
  { id:'korean-chicken-bibim-noodles', sourceId:'slice3-27', name:'บิบิมกุกซูไก่แบบเบา', englishName:'Light Korean Chicken Bibim Noodles', category:'Quick meals', cuisine:'Korean', servings:2, prepMinutes:15, cookMinutes:14, ingredients:[{item:'Whole-wheat noodles, cooked',amount:'250 g'},{item:'Skinless chicken breast, sliced',amount:'240 g'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Carrot, julienned',amount:'1 medium'},{item:'Gochujang',amount:'1 tbsp'},{item:'Rice vinegar',amount:'1½ tbsp'},{item:'Sesame oil',amount:'1 tsp'},{item:'Sesame seeds',amount:'1 tsp'}], instructions:['Pan-sear chicken until cooked through, then slice.','Whisk gochujang, rice vinegar and sesame oil with 2 tablespoons of water.','Toss noodles, cucumber and carrot with the sauce.','Top with chicken and sesame seeds and serve slightly chilled.'], nutrition:{kcal:420,protein:30,carbs:50,fat:10,fiber:7,sodium:620}, tags:['High protein','Quick','Dairy-free'], accent:'red' },
  { id:'chinese-ginger-scallion-prawns', sourceId:'slice3-28', name:'กุ้งผัดขิงต้นหอม', englishName:'Chinese Ginger-Scallion Prawns', category:'Quick meals', cuisine:'Chinese', servings:2, prepMinutes:10, cookMinutes:10, ingredients:[{item:'Prawns, peeled',amount:'260 g'},{item:'Bok choy, chopped',amount:'220 g'},{item:'Ginger, julienned',amount:'1 tbsp'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Oyster sauce',amount:'1 tbsp'},{item:'Reduced-sodium soy sauce',amount:'1 tsp'},{item:'Sesame oil',amount:'1 tsp'},{item:'Spring onion, sliced',amount:'2 stalks'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Warm sesame oil and stir-fry ginger and garlic until fragrant.','Add prawns and cook until almost opaque.','Add bok choy with 3 tablespoons of water, cover for 2 minutes, then add oyster sauce and soy sauce.','Toss until the prawns are fully cooked, fold in spring onion and serve with rice.'], nutrition:{kcal:390,protein:30,carbs:42,fat:10,fiber:5,sodium:760}, tags:['High protein','Quick','Dairy-free'], accent:'lime' },
  {"id":"chinese-tofu-broccoli-sesame","sourceId":"slice3-29","name":"เต้าหู้ผัดบรอกโคลีงา","englishName":"Chinese Tofu Broccoli Sesame Stir-fry","category":"Plant-forward","cuisine":"Chinese","servings":2,"prepMinutes":12,"cookMinutes":12,"ingredients":[{"item":"Firm tofu, cubed","amount":"300 g"},{"item":"Broccoli florets","amount":"280 g"},{"item":"Mushrooms, sliced","amount":"120 g"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Ginger, grated","amount":"1 tsp"},{"item":"Reduced-sodium soy sauce","amount":"2 tbsp"},{"item":"Sesame seeds","amount":"1 tsp"},{"item":"Neutral oil","amount":"1 tsp"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Rice vinegar","amount":"1 tbsp"},{"item":"Brown sugar","amount":"1 tsp"}],"instructions":["Pat tofu dry, heat oil in a non-stick pan and sear tofu until golden on two sides; set aside.","Briefly stir-fry garlic and ginger, then add broccoli, mushrooms and 3 tablespoons of water. Cover until crisp-tender, then uncover to evaporate excess water.","Mix soy sauce, rice vinegar and sugar with 2 tablespoons of water. Return tofu, add the sauce and toss over medium-high heat for 1–2 minutes until a thin glaze coats everything.","Finish with sesame and serve with brown rice."],"nutrition":{"kcal":450,"protein":37,"carbs":45,"fat":18,"fiber":10,"sodium":666},"tags":["Vegetarian","Plant protein","Fiber-rich"],"accent":"green"},
  {"id":"chinese-steamed-tofu-egg-custard","sourceId":"slice3-30","name":"เต้าหู้ไข่นึ่งเห็ด","englishName":"Chinese Steamed Tofu Egg Custard","category":"Plant-forward","cuisine":"Chinese","servings":2,"prepMinutes":12,"cookMinutes":24,"ingredients":[{"item":"Firm tofu, cubed","amount":"200 g"},{"item":"Eggs","amount":"3"},{"item":"Low-sodium vegetable stock","amount":"300 ml"},{"item":"Mushrooms, sliced","amount":"120 g"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Spring onion, sliced","amount":"2 stalks"},{"item":"Sesame seeds","amount":"1 tsp"},{"item":"Brown rice, cooked","amount":"1 cup"}],"instructions":["Use a shallow 20 cm heatproof dish with the custard mixture no deeper than 3 cm. Whisk eggs with vegetable stock and soy sauce, skim off foam, and pour over tofu.","Cut mushrooms into thin slices and scatter over the surface. Cover the dish with foil or a heatproof lid and steam over gently simmering water for 18–22 minutes, until the center is just set with a slight wobble and mushrooms are cooked.","If the center is still liquid, steam another 2–3 minutes and check again. Rest for 2 minutes, then top with spring onion and sesame.","Serve with brown rice."],"nutrition":{"kcal":420,"protein":24,"carbs":44,"fat":16,"fiber":4,"sodium":690},"tags":["Vegetarian","Balanced","Light"],"accent":"aqua"},
  { id:'chinese-prawn-egg-drop-soup', sourceId:'slice3-31', name:'ซุปไข่กุ้งและข้าวโพด', englishName:'Chinese Prawn Egg-Drop Soup', category:'Quick meals', cuisine:'Chinese', servings:2, prepMinutes:10, cookMinutes:15, ingredients:[{item:'Prawns, peeled',amount:'220 g'},{item:'Eggs',amount:'2'},{item:'Low-sodium stock',amount:'700 ml'},{item:'Mushrooms, sliced',amount:'150 g'},{item:'Corn kernels',amount:'½ cup'},{item:'Ginger, julienned',amount:'1 tbsp'},{item:'Reduced-sodium soy sauce',amount:'1 tsp'},{item:'Spring onion, sliced',amount:'2 stalks'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Simmer stock with ginger and mushrooms for 5 minutes.','Add corn and prawns and cook until the prawns are almost opaque.','Stir the soup in one direction while slowly pouring in beaten eggs; season with soy sauce.','Finish with spring onion and serve with brown rice.'], nutrition:{kcal:350,protein:28,carbs:40,fat:8,fiber:4,sodium:620}, tags:['High protein','Quick','Light'], accent:'gold' },
  {"id":"chinese-beef-celery-rice-noodles","sourceId":"slice3-32","name":"ผัดเส้นข้าวเนื้อขึ้นฉ่าย","englishName":"Chinese Beef Celery Rice Noodles","category":"Quick meals","cuisine":"Chinese","servings":2,"prepMinutes":12,"cookMinutes":12,"ingredients":[{"item":"Lean beef strips","amount":"260 g"},{"item":"Rice noodles, dry","amount":"100 g"},{"item":"Celery, sliced","amount":"1 cup"},{"item":"Carrot, julienned","amount":"1 medium"},{"item":"Bok choy, chopped","amount":"180 g"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Reduced-sodium soy sauce","amount":"2 tbsp"},{"item":"Neutral oil","amount":"1 tsp"},{"item":"Rice vinegar","amount":"2 tsp"},{"item":"Brown sugar","amount":"1 tsp"}],"instructions":["Cook rice noodles until just tender according to the packet and drain. Mix soy sauce, rice vinegar, sugar and 3 tablespoons of water.","Heat oil and brown beef in one layer; set aside. Stir-fry garlic briefly in the same pan.","Add celery, carrot and bok choy with 3 tablespoons of water and cook until crisp-tender; evaporate excess water.","Return beef with noodles and the measured sauce. Toss over high heat for 1–2 minutes until beef is cooked and noodles are hot and evenly coated; add a splash of water only if noodles stick."],"nutrition":{"kcal":451,"protein":35,"carbs":50,"fat":11,"fiber":3,"sodium":874},"tags":["High protein","Quick","Dairy-free"],"accent":"blue"},
  {"id":"chinese-chickpea-lettuce-cups","sourceId":"slice3-33","name":"ผักกาดหอมห่อถั่วชิกพีแบบจีน","englishName":"Chinese Chickpea Lettuce Cups","category":"Plant-forward","cuisine":"Chinese","servings":2,"prepMinutes":15,"cookMinutes":12,"ingredients":[{"item":"Chickpeas, rinsed","amount":"1½ cups"},{"item":"Mushrooms, finely chopped","amount":"200 g"},{"item":"Bell pepper, diced","amount":"1 medium"},{"item":"Butter lettuce leaves","amount":"12 leaves"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Ginger, minced","amount":"1 tbsp"},{"item":"Reduced-sodium soy sauce","amount":"2 tbsp"},{"item":"Sesame seeds","amount":"1 tsp"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Sesame oil","amount":"2 tsp"},{"item":"Rice vinegar","amount":"1 tbsp"}],"instructions":["Heat sesame oil in a wide non-stick pan and cook mushrooms without added water for 5–6 minutes until their moisture evaporates and the edges brown.","Add bell pepper and cook for 2 minutes, then add garlic and ginger for 30 seconds.","Mix soy sauce and rice vinegar with 2 tablespoons of water. Add chickpeas and sauce and toss until hot and lightly glazed, crushing a few chickpeas to bind the filling.","Spoon brown rice and the mushroom-chickpea filling into lettuce leaves. Finish with sesame and fold to eat."],"nutrition":{"kcal":408,"protein":18,"carbs":64,"fat":10,"fiber":13,"sodium":865},"tags":["Vegan","Fiber-rich","Light"],"accent":"lime"},
  { id:'vietnamese-lemongrass-chicken-rice', sourceId:'slice3-34', name:'ข้าวไก่ย่างตะไคร้เวียดนาม', englishName:'Vietnamese Lemongrass Chicken Rice', category:'High protein', cuisine:'Vietnamese', servings:2, prepMinutes:15, cookMinutes:16, ingredients:[{item:'Skinless chicken thighs, sliced',amount:'280 g'},{item:'Lemongrass, minced',amount:'1 tbsp'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Fish sauce',amount:'1 tbsp'},{item:'Lime juice',amount:'1 tbsp'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Mint and coriander',amount:'1 cup'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Marinate chicken with lemongrass, garlic, fish sauce and half the lime juice for 10 minutes.','Grill or pan-sear until browned and cooked through, then rest for 2 minutes.','Slice the chicken and arrange it with cucumber and herbs.','Serve with brown rice and the remaining lime juice.'], nutrition:{kcal:440,protein:32,carbs:43,fat:15,fiber:5,sodium:760}, tags:['High protein','Meal prep','Dairy-free'], accent:'gold' },
  {"id":"vietnamese-beef-vermicelli-salad","sourceId":"slice3-35","name":"ยำเส้นหมี่เนื้อเวียดนาม","englishName":"Vietnamese Beef Vermicelli Salad","category":"Light bowls","cuisine":"Vietnamese","servings":2,"prepMinutes":15,"cookMinutes":12,"ingredients":[{"item":"Lean beef strips","amount":"240 g"},{"item":"Rice vermicelli, dry","amount":"100 g"},{"item":"Lettuce, shredded","amount":"120 g"},{"item":"Cucumber, sliced","amount":"1 small"},{"item":"Mint leaves","amount":"½ cup"},{"item":"Carrot, julienned","amount":"1 medium"},{"item":"Lime juice","amount":"2 tbsp"},{"item":"Fish sauce","amount":"1 tbsp"},{"item":"Roasted peanuts, chopped","amount":"1 tbsp"}],"instructions":["Cook rice vermicelli according to the packet, rinse briefly and drain.","Sear beef in a hot pan until just cooked and rest for 2 minutes.","Whisk lime juice and fish sauce with 2 tablespoons of water.","Build bowls with lettuce, noodles, cucumber, carrot, mint and beef; spoon over dressing and peanuts."],"nutrition":{"kcal":430,"protein":30,"carbs":48,"fat":12,"fiber":6,"sodium":740},"tags":["High protein","Light","Dairy-free"],"accent":"aqua"},
  {"id":"vietnamese-shrimp-lemongrass-rice","sourceId":"slice3-36","name":"ข้าวกุ้งตะไคร้เวียดนามกับผักดองเร็ว","englishName":"Vietnamese Lemongrass Shrimp Rice with Quick Pickles","category":"Quick meals","cuisine":"Vietnamese","servings":2,"prepMinutes":18,"cookMinutes":10,"ingredients":[{"item":"Prawns, peeled","amount":"240 g"},{"item":"Lemongrass, minced","amount":"1 tbsp"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Fish sauce","amount":"2 tsp"},{"item":"Lime juice","amount":"1 tbsp"},{"item":"Carrot, julienned","amount":"1 medium"},{"item":"Daikon, julienned","amount":"100 g"},{"item":"Rice vinegar","amount":"2 tbsp"},{"item":"Brown sugar","amount":"2 tsp"},{"item":"Bird’s eye chilli, sliced","amount":"1"},{"item":"Cucumber, sliced","amount":"1 small"},{"item":"Mint and coriander","amount":"½ cup"},{"item":"Jasmine rice, cooked","amount":"1 cup"}],"instructions":["Toss carrot and daikon with rice vinegar and half the sugar; stand for 15 minutes, tossing twice.","Coat prawns with lemongrass, garlic and half the fish sauce. Sear in a hot non-stick pan for about 2 minutes per side until opaque throughout.","Stir lime juice, chilli, remaining fish sauce and remaining sugar with 1 tablespoon of water into a dipping dressing.","Serve prawns with rice, cucumber, herbs and the quick-pickled carrot and daikon. Spoon the pickle liquid over the vegetables and serve the chilli-lime dressing alongside."],"nutrition":{"kcal":270,"protein":28,"carbs":37,"fat":1,"fiber":3,"sodium":572},"tags":["High protein","Quick","Dairy-free"],"accent":"lime"},
  {"id":"vietnamese-caramel-pork","sourceId":"slice3-37","name":"หมูคาราเมลเวียดนาม","englishName":"Vietnamese Caramel Pork with Greens","category":"High protein","cuisine":"Vietnamese","servings":2,"prepMinutes":12,"cookMinutes":16,"ingredients":[{"item":"Lean pork loin, thinly sliced","amount":"280 g"},{"item":"Fish sauce","amount":"1 tbsp"},{"item":"Brown sugar","amount":"1 tbsp"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Ground black pepper","amount":"½ tsp"},{"item":"Bok choy, chopped","amount":"200 g"},{"item":"Cucumber, sliced","amount":"1 small"},{"item":"Brown rice, cooked","amount":"1 cup"}],"instructions":["Pat the lean pork slices dry. Measure fish sauce, garlic and black pepper into a bowl; keep the sugar separate.","Heat sugar with 1 tablespoon of water in a non-stick pan over medium-low heat until dissolved and bubbling amber, about 2–3 minutes. Take off the heat and carefully add 3 tablespoons of water to stop the caramel darkening.","Return to medium heat, add pork and the fish-sauce mixture, and turn for 4–6 minutes until the pork is fully cooked. Reduce the liquid to a glossy coating; lower the heat and add a splash of water if it threatens to scorch.","Steam bok choy until tender-crisp. Rest the pork for 3 minutes, then serve with bok choy, cucumber and brown rice."],"nutrition":{"kcal":450,"protein":35,"carbs":44,"fat":15,"fiber":5,"sodium":760},"tags":["High protein","Balanced","Meal prep"],"accent":"coral"},
  { id:'vietnamese-tomato-tofu-braise', sourceId:'slice3-38', name:'เต้าหู้ตุ๋นมะเขือเทศเวียดนาม', englishName:'Vietnamese Tomato-Braised Tofu', category:'Plant-forward', cuisine:'Vietnamese', servings:2, prepMinutes:12, cookMinutes:18, ingredients:[{item:'Firm tofu, cubed',amount:'280 g'},{item:'Tomatoes, chopped',amount:'400 g'},{item:'Onion, sliced',amount:'1 small'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Ginger, grated',amount:'1 tsp'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Spinach',amount:'100 g'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Pan-sear tofu until lightly golden and set it aside.','Cook onion, garlic and ginger until fragrant, then add tomatoes and soy sauce and simmer until saucy.','Return tofu and simmer gently for 5 minutes, then fold in spinach until wilted.','Serve over brown rice.'], nutrition:{kcal:430,protein:23,carbs:55,fat:13,fiber:9,sodium:620}, tags:['Vegetarian','Plant protein','Fiber-rich'], accent:'red' },
  { id:'mediterranean-salmon-couscous', sourceId:'slice3-39', name:'คูสคูสแซลมอนเมดิเตอร์เรเนียน', englishName:'Mediterranean Salmon Couscous', category:'Light bowls', cuisine:'Mediterranean', servings:2, prepMinutes:15, cookMinutes:16, ingredients:[{item:'Salmon fillets',amount:'280 g'},{item:'Whole-wheat couscous, cooked',amount:'150 g'},{item:'Chickpeas, rinsed',amount:'½ cup'},{item:'Zucchini, sliced',amount:'1 medium'},{item:'Cherry tomatoes',amount:'150 g'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Parsley, chopped',amount:'½ cup'},{item:'Lemon juice',amount:'2 tbsp'},{item:'Olive oil',amount:'1 tsp'}], instructions:['Toss zucchini and cherry tomatoes with olive oil and roast at 200°C until tender.','Bake or pan-sear salmon until it flakes easily, then rest and break into large pieces.','Combine couscous, chickpeas, cucumber and parsley.','Add roasted vegetables and salmon, dress with lemon juice and serve.'], nutrition:{kcal:480,protein:30,carbs:50,fat:18,fiber:8,sodium:250}, tags:['High protein','Omega-rich','Meal prep'], accent:'aqua' },
  {"id":"greek-chicken-sweet-potato-tray","sourceId":"slice3-40","name":"ไก่และมันหวานอบถาดสไตล์กรีก","englishName":"Greek Chicken Sweet Potato Tray","category":"High protein","cuisine":"Mediterranean","servings":2,"prepMinutes":15,"cookMinutes":30,"ingredients":[{"item":"Skinless chicken breast, sliced","amount":"280 g"},{"item":"Sweet potato, cut into 1.5 cm cubes","amount":"300 g"},{"item":"Zucchini, sliced","amount":"1 medium"},{"item":"Greek yogurt","amount":"3 tbsp"},{"item":"Lemon juice","amount":"2 tbsp"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Dried oregano","amount":"1 tsp"},{"item":"Olive oil","amount":"1 tsp"}],"instructions":["Toss 1.5 cm sweet-potato cubes and zucchini with olive oil and half the oregano. Roast at 200°C for 15 minutes.","Mix chicken slices no thicker than 1 cm with garlic, 1 tablespoon of the lemon juice and remaining oregano. Add to the tray in one layer and roast for 10–12 minutes until chicken is fully cooked and sweet potato is fork-tender.","Stir the remaining 1 tablespoon lemon juice into the yogurt for the sauce.","Rest chicken for 3 minutes, then serve with the vegetables and yogurt sauce."],"nutrition":{"kcal":356,"protein":38,"carbs":36,"fat":6,"fiber":6,"sodium":162},"tags":["High protein","Balanced","Meal prep"],"accent":"gold"},
  {"id":"italian-lentil-bolognese","sourceId":"slice3-41","name":"สปาเกตตีโบโลเนสถั่วเลนทิล","englishName":"Italian Lentil Bolognese","category":"Plant-forward","cuisine":"Italian","servings":2,"prepMinutes":12,"cookMinutes":24,"ingredients":[{"item":"Green lentils, cooked","amount":"1½ cups"},{"item":"Whole-wheat spaghetti, dry","amount":"150 g"},{"item":"Crushed tomatoes","amount":"400 g"},{"item":"Onion, diced","amount":"1 small"},{"item":"Carrot, diced","amount":"1 medium"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Olive oil","amount":"1 tsp"},{"item":"Dried oregano","amount":"1 tsp"},{"item":"Vegetarian-certified hard cheese, grated (microbial rennet)","amount":"15 g"}],"instructions":["Cook spaghetti until just tender and reserve ½ cup cooking water.","Warm olive oil and soften onion and carrot; add garlic and oregano for 30 seconds.","Add crushed tomatoes and lentils and simmer until thickened, loosening with a splash of pasta water if needed.","Toss with spaghetti and finish with the vegetarian-certified hard cheese; check that the cheese uses microbial or plant rennet."],"nutrition":{"kcal":582,"protein":30,"carbs":106,"fat":8,"fiber":24,"sodium":283},"tags":["Vegetarian","Fiber-rich","Balanced"],"accent":"red"},
  {"id":"italian-tuna-white-bean-pasta","sourceId":"slice3-42","name":"พาสต้าทูน่าถั่วขาวแบบอิตาเลียน","englishName":"Italian Tuna and White Bean Pasta","category":"Quick meals","cuisine":"Italian","servings":2,"prepMinutes":10,"cookMinutes":16,"ingredients":[{"item":"Tuna in spring water, drained","amount":"180 g"},{"item":"Whole-wheat penne, dry","amount":"150 g"},{"item":"White beans, rinsed","amount":"1 cup"},{"item":"Tomatoes, chopped","amount":"200 g"},{"item":"Spinach","amount":"100 g"},{"item":"Lemon juice","amount":"1 tbsp"},{"item":"Olive oil","amount":"1 tsp"},{"item":"Garlic, minced","amount":"1 clove"}],"instructions":["Cook penne until just tender and reserve ½ cup cooking water.","Warm olive oil with garlic, add tomatoes and simmer for 5 minutes.","Add tuna, white beans and spinach and cook until hot and the spinach wilts.","Toss with pasta, lemon juice and enough cooking water to make a light sauce."],"nutrition":{"kcal":524,"protein":42,"carbs":80,"fat":6,"fiber":14,"sodium":451},"tags":["High protein","Fiber-rich","Quick"],"accent":"aqua"},
  { id:'spanish-chickpea-spinach-stew', sourceId:'slice3-43', name:'สตูว์ถั่วชิกพีผักโขมสเปน', englishName:'Spanish Chickpea Spinach Stew', category:'Plant-forward', cuisine:'Spanish', servings:2, prepMinutes:12, cookMinutes:24, ingredients:[{item:'Chickpeas, rinsed',amount:'1½ cups'},{item:'Tomatoes, chopped',amount:'400 g'},{item:'Spinach',amount:'150 g'},{item:'Bell pepper, diced',amount:'1 medium'},{item:'Onion, diced',amount:'1 small'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Paprika',amount:'1 tsp'},{item:'Ground cumin',amount:'1 tsp'},{item:'Olive oil',amount:'1 tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Warm olive oil and soften onion and bell pepper.','Add garlic, paprika and cumin and cook for 30 seconds.','Add tomatoes and chickpeas and simmer until thick and flavorful.','Fold in spinach until wilted and serve over brown rice.'], nutrition:{kcal:450,protein:16,carbs:70,fat:12,fiber:16,sodium:360}, tags:['Vegan','Fiber-rich','Comforting'], accent:'red' },
  { id:'mediterranean-turkey-stuffed-zucchini', sourceId:'slice3-44', name:'ซูกินียัดไส้ไก่งวงเมดิเตอร์เรเนียน', englishName:'Mediterranean Turkey-Stuffed Zucchini', category:'High protein', cuisine:'Mediterranean', servings:2, prepMinutes:15, cookMinutes:25, ingredients:[{item:'Lean turkey mince',amount:'280 g'},{item:'Zucchini, halved',amount:'2 medium'},{item:'Cooked quinoa',amount:'1 cup'},{item:'Tomatoes, chopped',amount:'200 g'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Dried oregano',amount:'1 tsp'},{item:'Feta cheese, crumbled',amount:'40 g'},{item:'Olive oil',amount:'1 tsp'}], instructions:['Scoop a shallow channel from the zucchini halves and place them on a tray.','Cook turkey with garlic and oregano until browned, then fold in the quinoa and tomatoes.','Fill the zucchini, drizzle with olive oil and bake at 200°C until tender and the filling is hot.','Scatter with feta and serve.'], nutrition:{kcal:450,protein:34,carbs:42,fat:16,fiber:8,sodium:520}, tags:['High protein','Balanced','Meal prep'], accent:'lime' },
  { id:'french-white-bean-ratatouille', sourceId:'slice3-45', name:'ราตาตุยถั่วขาว', englishName:'French White Bean Ratatouille', category:'Plant-forward', cuisine:'International', servings:2, prepMinutes:15, cookMinutes:28, ingredients:[{item:'White beans, rinsed',amount:'1½ cups'},{item:'Zucchini, sliced',amount:'1 medium'},{item:'Eggplant, cubed',amount:'250 g'},{item:'Tomatoes, chopped',amount:'400 g'},{item:'Bell pepper, diced',amount:'1 medium'},{item:'Onion, diced',amount:'1 small'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Olive oil',amount:'1 tsp'},{item:'Dried oregano',amount:'1 tsp'},{item:'Whole-wheat bread',amount:'2 slices'}], instructions:['Warm olive oil and soften onion, bell pepper and eggplant until the edges color.','Add zucchini, garlic and oregano and cook for 1 minute.','Add tomatoes and white beans and simmer until the vegetables are tender and the sauce is thick.','Serve with toasted whole-wheat bread.'], nutrition:{kcal:450,protein:17,carbs:68,fat:12,fiber:17,sodium:420}, tags:['Vegan','Fiber-rich','Comforting'], accent:'violet' },
  { id:'greek-shrimp-tomato-feta', sourceId:'slice3-46', name:'กุ้งตุ๋นมะเขือเทศเฟต้าแบบกรีก', englishName:'Greek Shrimp with Tomato and Feta', category:'High protein', cuisine:'Mediterranean', servings:2, prepMinutes:12, cookMinutes:16, ingredients:[{item:'Prawns, peeled',amount:'260 g'},{item:'Tomatoes, chopped',amount:'400 g'},{item:'Spinach',amount:'100 g'},{item:'Onion, diced',amount:'1 small'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Feta cheese, crumbled',amount:'50 g'},{item:'Olive oil',amount:'1 tsp'},{item:'Lemon juice',amount:'1 tbsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Warm olive oil and soften onion and garlic.','Add tomatoes and simmer until slightly reduced.','Add prawns and spinach and cook until the prawns are opaque and the spinach wilts.','Finish with lemon juice and feta and serve with brown rice.'], nutrition:{kcal:450,protein:31,carbs:45,fat:15,fiber:6,sodium:680}, tags:['High protein','Balanced','Gluten-free'], accent:'coral' },
  { id:'mexican-shrimp-fajita-rice', sourceId:'slice3-47', name:'ข้าวกุ้งฟาฮิตาเม็กซิกัน', englishName:'Mexican Shrimp Fajita Rice', category:'Quick meals', cuisine:'Mexican', servings:2, prepMinutes:12, cookMinutes:12, ingredients:[{item:'Prawns, peeled',amount:'260 g'},{item:'Brown rice, cooked',amount:'1 cup'},{item:'Bell pepper, sliced',amount:'1 medium'},{item:'Onion, sliced',amount:'1 medium'},{item:'Corn kernels',amount:'½ cup'},{item:'Tomato salsa',amount:'½ cup'},{item:'Lime juice',amount:'1 tbsp'},{item:'Ground cumin',amount:'1 tsp'},{item:'Olive oil',amount:'1 tsp'}], instructions:['Toss prawns with cumin and half the lime juice.','Warm olive oil and cook onion and bell pepper until lightly charred, then add prawns and cook until opaque.','Fold in corn and warm through.','Serve over brown rice with salsa and the remaining lime juice.'], nutrition:{kcal:420,protein:29,carbs:54,fat:9,fiber:8,sodium:620}, tags:['High protein','Quick','Dairy-free'], accent:'gold' },
  {"id":"mexican-chicken-bean-tortilla","sourceId":"slice3-48","name":"โตสตาดาไก่ถั่วดำเม็กซิกัน","englishName":"Mexican Chicken and Black Bean Tostadas","category":"Quick meals","cuisine":"Mexican","servings":2,"prepMinutes":15,"cookMinutes":18,"ingredients":[{"item":"Skinless chicken breast, sliced","amount":"240 g"},{"item":"Whole-wheat tortillas","amount":"2 medium"},{"item":"Black beans, rinsed","amount":"1 cup"},{"item":"Bell pepper, diced","amount":"1 medium"},{"item":"Onion, diced","amount":"1 small"},{"item":"Tomato salsa","amount":"½ cup"},{"item":"Ground cumin","amount":"1 tsp"},{"item":"Paprika","amount":"1 tsp"},{"item":"Olive oil","amount":"1 tsp"},{"item":"Lime juice","amount":"1 tbsp"},{"item":"Coriander leaves","amount":"¼ cup"}],"instructions":["Toast the whole-wheat tortillas on a rack at 190°C for 6–8 minutes until crisp, watching the edges. These open tostadas are served flat, not rolled.","Heat oil and cook chicken, cumin and paprika in a non-stick pan until lightly browned and fully cooked, about 5–6 minutes; transfer to a clean plate and chop.","Cook onion and bell pepper in the same pan with 2 tablespoons of water until tender. Add black beans and half the salsa, mash coarsely, and reduce until thick enough to spread.","Spread the bean mixture over the crisp tortillas, top with chicken, remaining salsa, lime juice and coriander. Serve immediately while crisp."],"nutrition":{"kcal":478,"protein":41,"carbs":57,"fat":10,"fiber":15,"sodium":952},"tags":["High protein","Balanced","Quick"],"accent":"lime"},
  {"id":"savory-oats-egg-mushrooms","sourceId":"slice3-49","name":"โจ๊กข้าวโอ๊ตเค็มไข่และเห็ด","englishName":"Savory Oats with Egg and Mushrooms","category":"Quick meals","cuisine":"International","servings":2,"prepMinutes":8,"cookMinutes":12,"ingredients":[{"item":"Oats","amount":"1 cup"},{"item":"Eggs","amount":"2"},{"item":"Mushrooms, sliced","amount":"180 g"},{"item":"Spinach","amount":"100 g"},{"item":"Low-sodium vegetable stock","amount":"350 ml"},{"item":"Reduced-sodium soy sauce","amount":"1 tsp"},{"item":"Sesame oil","amount":"1 tsp"},{"item":"Spring onion, sliced","amount":"2 stalks"},{"item":"Sesame seeds","amount":"1 tsp"}],"instructions":["Simmer oats and vegetable stock for 5–7 minutes, stirring until creamy; add a splash of water if needed.","Warm sesame oil in a non-stick pan and brown mushrooms; add spinach and cook until wilted. Transfer vegetables to a bowl.","Crack eggs into the same non-stick pan without extra oil. Add 1 tablespoon of water at the edge, cover and cook gently for 3–4 minutes until whites are fully set; cook longer for firm yolks.","Divide oats and vegetables between two bowls, top each with an egg, and finish with soy sauce, spring onion and sesame."],"nutrition":{"kcal":298,"protein":17,"carbs":35,"fat":11,"fiber":7,"sodium":306},"tags":["Vegetarian","Balanced","Quick"],"accent":"aqua"},
  {"id":"one-pan-chicken-vegetable-quinoa","sourceId":"slice3-50","name":"ควินัวไก่และผักในกระทะเดียว","englishName":"One-Pan Chicken Vegetable Quinoa","category":"High protein","cuisine":"International","servings":2,"prepMinutes":12,"cookMinutes":15,"ingredients":[{"item":"Skinless chicken breast, diced","amount":"280 g"},{"item":"Cooked quinoa","amount":"1 cup"},{"item":"Broccoli florets","amount":"180 g"},{"item":"Zucchini, sliced","amount":"1 medium"},{"item":"Cherry tomatoes","amount":"150 g"},{"item":"Low-sodium stock","amount":"80 ml"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Lemon juice","amount":"1 tbsp"},{"item":"Olive oil","amount":"1 tsp"}],"instructions":["Heat olive oil in a wide non-stick pan and brown chicken in one layer for 4–5 minutes.","Add garlic for 30 seconds, then broccoli, zucchini, tomatoes and 80 ml stock. Cover and simmer for 4–5 minutes until chicken is fully cooked and vegetables are crisp-tender.","Uncover and reduce until no pool of stock remains, about 1–2 minutes. Fold in the already-cooked quinoa and toss just until hot; do not rely on cooked quinoa to absorb a large volume of liquid.","Turn off the heat, finish with lemon juice and serve."],"nutrition":{"kcal":368,"protein":40,"carbs":33,"fat":9,"fiber":7,"sodium":131},"tags":["High protein","Balanced","Meal prep"],"accent":"green"},
]

